CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,thread TEXT NOT NULL,role TEXT NOT NULL,content TEXT NOT NULL,photos TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS spaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,icon TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS space_applets(applet_id TEXT PRIMARY KEY,space_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chats(id TEXT PRIMARY KEY,space_id TEXT NOT NULL,title TEXT NOT NULL,launch TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS chat_tools(id TEXT PRIMARY KEY,thread TEXT NOT NULL,message_id INTEGER,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS build_drafts(chat_id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS build_plans(chat_id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,space_id TEXT NOT NULL,key TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,due_at TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0,UNIQUE(space_id,key));
CREATE TABLE IF NOT EXISTS secrets(name TEXT PRIMARY KEY,description TEXT NOT NULL,ciphertext TEXT NOT NULL,origins TEXT NOT NULL DEFAULT '[]',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY,space_id TEXT NOT NULL,key TEXT NOT NULL,title TEXT NOT NULL,prompt TEXT NOT NULL,cron TEXT,timezone TEXT NOT NULL,model TEXT NOT NULL,next_run TEXT,enabled INTEGER NOT NULL DEFAULT 1,last_run TEXT,last_error TEXT,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(space_id,key));
CREATE TABLE IF NOT EXISTS push_subscriptions(endpoint TEXT PRIMARY KEY,subscription TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_deliveries(endpoint TEXT NOT NULL,notification_id TEXT NOT NULL,fingerprint TEXT NOT NULL,PRIMARY KEY(endpoint,notification_id));
CREATE TABLE IF NOT EXISTS voice_actions(id TEXT PRIMARY KEY,chat_id TEXT NOT NULL,status TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chat_jobs(id TEXT PRIMARY KEY,space_id TEXT NOT NULL,chat_id TEXT NOT NULL,status TEXT NOT NULL,fingerprint TEXT NOT NULL,data TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS chat_jobs_running_space ON chat_jobs(space_id) WHERE status='running';
CREATE TABLE IF NOT EXISTS photos(id TEXT PRIMARY KEY,owner TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,bytes INTEGER NOT NULL,data BLOB NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS messages_thread_id ON messages(thread,id);
CREATE INDEX IF NOT EXISTS chats_space ON chats(space_id);
CREATE TRIGGER IF NOT EXISTS notification_delete_deliveries AFTER DELETE ON notifications BEGIN DELETE FROM push_deliveries WHERE notification_id=OLD.id; END;
CREATE TRIGGER IF NOT EXISTS subscription_delete_deliveries AFTER DELETE ON push_subscriptions BEGIN DELETE FROM push_deliveries WHERE endpoint=OLD.endpoint; END;
DELETE FROM push_deliveries WHERE NOT EXISTS(SELECT 1 FROM notifications WHERE id=notification_id) OR NOT EXISTS(SELECT 1 FROM push_subscriptions WHERE endpoint=push_deliveries.endpoint);
